WITH valid AS (SELECT *, DATE_FORMAT(event_time, 'MMM yyyy') AS event_time_label FROM web_events WHERE page IS NOT NULL), filtered AS (SELECT *, LENGTH(event_type) AS event_type_length, COALESCE(page, 'OTHER') AS page_clean FROM valid WHERE event_time > TO_TIMESTAMP('2024-03-24 18:00:00')), base AS (SELECT *, UPPER(page) AS page_upper, COALESCE(page, 'DIRECT') AS page_filled FROM filtered WHERE duration_sec > 172), filtered_web_events AS (SELECT *, INITCAP(TRIM(event_type)) AS event_type_title, COALESCE(page, 'UNKNOWN') AS page_clean_2 FROM base WHERE event_time < '2024-04-09') SELECT id, event_time, duration_sec, event_time_label, event_type_length, page_clean, page_upper, page_filled, page_clean_2 FROM filtered_web_events ORDER BY id ASC, event_time ASC LIMIT 10
